[{"name_path": "listIgnoredFilesOutsideNodeModules", "kind": "Function", "relative_path": "src/core/guard.ts", "body_location": {"start_line": 70, "end_line": 95}, "body": "function listIgnoredFilesOutsideNodeModules(repo: string): { files: string[]; failed: boolean } {
  try {
    const out = git(
      repo,
      'ls-files',
      '--others',
      '--ignored',
      '--exclude-standard',
      // KHÔNG --directory: kèm pathspec loại trừ, git liệt kê cả thư mục cha (vd packages/) → xoá nhầm source.
      '-z',
      '--',
      '.',
      ':(exclude,glob)**/node_modules/**',
      ':(exclude)node_modules'
    );
    const files = out
      .split('\0')
      .map((p) => p.replace(/\\/g, '/'))
      .filter(Boolean)
      .filter((p) => !p.split('/').includes('node_modules'))
      .sort();
    return { files, failed: false };
  } catch {
    return { files: [], failed: true };
  }
}"}]

